  function str(v) {
    if (typeof v !== 'string' || v[0] !== '"') return v;
    return v.slice(1, -1).replace(/\\(.)/g, '$1');
  }

  /** Quote free text as a SOP Lang string value. */
  function quote(s) {
    return `"${String(s).replace(/(["\\])/g, '\\$1')}"`;
  }
  return { SopError, tokenize, parse, format, cloneWire, str, quote };
