    sub: sameUnit((a, b) => a - b),
    min: sameUnit((a, b) => Math.min(a, b)),
    max: sameUnit((a, b) => Math.max(a, b)),
    mul: combine((a, b) => a * b, mulUnit),
    div: combine((a, b) => a / b, divUnit),
